function validate([plantTime, growTime]) {
  if (!Array.isArray(plantTime) || plantTime.length < 1 || plantTime.length > 100000) return 'plantTime needs 1 to 10^5 values.';
  if (!Array.isArray(growTime) || growTime.length !== plantTime.length) return 'growTime must be as long as plantTime.';
  const ok = v => Number.isInteger(v) && v >= 1 && v <= 10000;
  if (!plantTime.every(ok) || !growTime.every(ok)) return 'Every time is an integer from 1 to 10^4.';
  return null;
}

