function earliestFullBloom(plantTime, growTime) {
  const order = plantTime.map((_, i) => i);
  order.sort((a, b) => growTime[b] - growTime[a]);

  let planted = 0;
  let bloom = 0;
  for (const i of order) {
    planted += plantTime[i];
    bloom = Math.max(bloom, planted + growTime[i]);
  }
  return bloom;
}

