function earliestFullBloom(plantTime, growTime) {
  // Try every order of planting the seeds one after another and keep the best last bloom day.
  const n = plantTime.length;
  let best = Infinity;
  const used = new Array(n).fill(false);
  const search = (count, day, latest) => {
    if (latest >= best) return;
    if (count === n) { best = latest; return; }
    for (let s = 0; s < n; s++) {
      if (used[s]) continue;
      used[s] = true;
      const done = day + plantTime[s];
      search(count + 1, done, Math.max(latest, done + growTime[s]));
      used[s] = false;
    }
  };
  search(0, 0, 0);
  return best;
}

