function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 2000 : pick(1, 6);
  const top = size === 'large' ? [10, 1000, 10000][pick(0, 2)] : [3, 8, 10000][pick(0, 2)];
  const plantTime = Array.from({ length: n }, () => pick(1, top));
  const growTime = Array.from({ length: n }, () => pick(1, top));
  return [plantTime, growTime];
}
